 async Task SelectRoom(RoomInfo next)
 {
  if(room?.Code==next.Code&&relay!=null)return;Disconnect();room=next;api.SelectRoom(next.Code);api.SetRoomRole(next.Role);judge=next.Role is "leader" or "cohost" or "judge";SideRoom.Text=next.Name+" · "+next.RoleLabel;CurrentRoomName.Text=next.Name;CurrentRoomRole.Text=next.RoleLabel+" · лидер "+next.LeaderName;CurrentRoomCode.Text=next.Code;SetRole();
