 async void Start_Click(object s,RoutedEventArgs e)=>await StartCountdown();async void Cancel_Click(object s,RoutedEventArgs e)=>await CancelCountdown();
 async Task StartCountdown(){if(relay==null||!judge||!relay.Connected)return;if(!int.TryParse(CountdownSeconds.Text,out int seconds)||seconds<1||seconds>60){Message.Text="Отсчёт должен быть от 1 до 60 секунд.";return;}await relay.Control("start",RoundInput.Text,seconds*1000);}async Task CancelCountdown(){if(relay!=null&&judge&&relay.Connected)await relay.Control("cancel",RoundInput.Text);}void HotStart(){if(judge&&relay?.Connected==true)_=StartCountdown();}void HotCancel(){if(judge&&relay?.Connected==true)_=CancelCountdown();}
 void Tick()
 {
  if(demo)return;if(relay==null){ConnectionStatus.Text=room==null?"Группа не выбрана":"Отключено";ConnectionDot.Fill=Paint.Brush("#55555B");return;}
  bool online=relay.Connected;var clock=relay.Clock;bool good=online&&clock.Synced&&state!=null;bool active=state?.StartAt is double at&&RelayClient.Now+clock.Offset<at+3000;StartButton.IsEnabled=judge&&good&&!active;CancelButton.IsEnabled=judge&&online;ConnectionStatus.Text=online?"Онлайн · "+room?.Code:"Переподключение";ConnectionDot.Fill=Paint.Brush(online?"#31D67B":"#F0A23A");SyncLabel.Text=clock.Synced?$"RTT {clock.Rtt:F0} мс":"Синхронизация…";
  string text,hint;int light=-1,hudLight=-1;if(!online){text="Нет связи";hint="Не стартуйте";}else if(!good){text="Сверка";hint="Синхронизация времени";}else if(state!.StartAt==null){text="Готовы?";hint=judge?"F8 — запустить отсчёт":"Ожидаем команду судьи";}else if(!judge&&!state.Seated){text="Зритель";hint="Старт назначен до подключения";}else{double left=state.StartAt.Value-(RelayClient.Now+clock.Offset);if(left>0){int second=(int)Math.Ceiling(left/1000),total=Math.Max(1,state.CountdownMs/1000);text=second.ToString("00");hint="Приготовиться";double pulse=(1000-(left%1000))%1000;if(pulse<360){hudLight=Math.Clamp(total-second,0,4);light=second<=2?1:0;}}else if(left>-650){text="СТАРТ";hint="Поехали!";light=2;hudLight=5;}else{text="В заезде";hint="Ожидаем следующий старт";}}
  SignalText.Text=text;SignalText.FontSize=text.Length>8?34:text.Length>5?46:80;SignalHint.Text=hint;string[] colors=["#F20D4F","#F4B43A","#59E26F"];SignalText.Foreground=Paint.Brush(light>=0?colors[light]:"#F4F4F5");var lamps=new[]{RedLamp,AmberLamp,GreenLamp};for(int i=0;i<3;i++)lamps[i].Fill=Paint.Brush(i==light?colors[i]:"#252529");hud?.Display(text,state?.Label??"DRIFTSTART",hudLight,hint.ToUpperInvariant());
 }
  async void Events_Click(object s,RoutedEventArgs e){if(room==null){Message.Text="Сначала выбери группу.";ShowPage("lobby");return;}ShowPage("events");if(events==null){events=new EventWindow(api);events.StartRequested+=label=>{RoundInput.Text=label;Message.Text="Пара отправлена в стартовый HUD.";ShowPage("race");};events.QualificationHudRequested+=(p,discipline)=>{EnsureJudgeHud();judgeHud!.Display(p,discipline);};events.QualificationHudUpdated+=(p,discipline)=>{if(judgeHud?.IsVisible==true)judgeHud.Display(p,discipline);};events.PairHudRequested+=(a,b,m,discipline)=>{EnsureJudgeHud();judgeHud!.DisplayPair(a,b,m,discipline);};events.PairHudUpdated+=(a,b,m,discipline)=>{if(judgeHud?.IsVisible==true)judgeHud.DisplayPair(a,b,m,discipline);};events.FullscreenRequested+=ShowTournamentFullscreen;EventHost.Content=events.TakeContent(this);await events.LoadEmbedded();}else await events.LoadEmbedded();}
  void EnsureJudgeHud(){if(judgeHud!=null)return;judgeHud=new JudgeHud();judgeHud.ScoreSubmitted+=async(p,attempt,score,discipline)=>{if(events!=null)await events.ScoreFromHud(p,attempt,score,discipline);};judgeHud.PairScoreSubmitted+=async(matchId,p,run,score,discipline)=>{if(events!=null)await events.ScorePairFromHud(matchId,p,run,score,discipline);};judgeHud.NavigateRequested+=direction=>events?.NavigateQualification(direction);}
  void ShowTournamentFullscreen(){if(EventHost.Content is not UIElement view)return;EventHost.Content=null;var full=new Window{Title="DriftStart — Турнирная сетка",WindowStyle=WindowStyle.None,WindowState=WindowState.Maximized,Background=Paint.Brush("#080809"),Content=view,Owner=this};full.PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Escape)full.Close();};full.Closed+=(_,_)=>{full.Content=null;EventHost.Content=view;};full.Show();}
 void ApplyHudSettings(){if(hud==null)return;hud.Configure(HudScale.Value,HudOpacity.Value,MoveHudCheck.IsChecked==true);if(ShowHudCheck.IsChecked==true)hud.Show();else hud.Hide();}void HudSettings_Changed(object s,RoutedEventArgs e){if(IsInitialized)ApplyHudSettings();}void HudSlider_Changed(object s,RoutedPropertyChangedEventArgs<double> e){if(IsInitialized)ApplyHudSettings();}void ResetHud_Click(object s,RoutedEventArgs e)=>hud?.Center();
